func (c *Client) applyEditors(ctx context.Context, req *http.Request, additionalEditors []RequestEditorFn) error {
	for _, r := range c.RequestEditors {
		if err := r(ctx, req); err != nil {
			return err
		}
	}
	for _, r := range additionalEditors {
		if err := r(ctx, req); err != nil {
			return err
		}
	}
	return nil
}

// ClientWithResponses builds on ClientInterface to offer response payloads
type ClientWithResponses struct {
	ClientInterface
}

// NewClientWithResponses creates a new ClientWithResponses, which wraps
// Client with return type handling
func NewClientWithResponses(server string, opts ...ClientOption) (*ClientWithResponses, error) {
	client, err := NewClient(server, opts...)
	if err != nil {
		return nil, err
	}
	return &ClientWithResponses{client}, nil
}

// WithBaseURL overrides the baseURL.
func WithBaseURL(baseURL string) ClientOption {
	return func(c *Client) error {
		newBaseURL, err := url.Parse(baseURL)
		if err != nil {
			return err
		}
		c.Server = newBaseURL.String()
		return nil
	}
}

// ClientWithResponsesInterface is the interface specification for the client with responses above.
type ClientWithResponsesInterface interface {

	// PostCollapseWithResponse Collapse envd's own anonymous heap into 2 MiB transparent hugepages before pause, so on resume envd touches fewer distinct guest-physical frames (each a cold fault). Best-effort.
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with POST /collapse (the `PostCollapse` operationId).
	PostCollapseWithResponse(ctx context.Context, reqEditors ...RequestEditorFn) (*PostCollapseResponse, error)

	// GetEnvsWithResponse Environment variables
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /envs (the `GetEnvs` operationId).
	GetEnvsWithResponse(ctx context.Context, reqEditors ...RequestEditorFn) (*GetEnvsResponse, error)

	// GetFilesWithResponse Download a file
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /files (the `GetFiles` operationId).
	GetFilesWithResponse(ctx context.Context, params *GetFilesParams, reqEditors ...RequestEditorFn) (*GetFilesResponse, error)

	// PostFilesWithBodyWithResponse Upload a file and ensure the parent directories exist. If the file exists, it will be overwritten.
	//
	// Any request header of the form `X-Metadata-<key>: <value>` is persisted
	// as a user-defined extended attribute on the uploaded file. The
	// `X-Metadata-` prefix is stripped and the remaining header name is
	// lowercased to form the metadata key; the resulting map is returned on
	// `EntryInfo` lookups (e.g. `Stat`, `ListDir`).
	//
	// Each upload replaces the file's metadata with the keys provided in
	// that request: keys previously stored but absent from the new request
	// are removed, and an upload that sends no `X-Metadata-*` header clears
	// all existing metadata.
	//
	// Both keys and values must be printable US-ASCII (bytes `0x20`-`0x7E`)
	// and are rejected with HTTP 400 otherwise. Each key is capped at 246
	// bytes (the Linux VFS xattr-name limit minus the namespace prefix), and
	// the combined size of all metadata on a file (keys plus values, with the
	// namespace prefix counted per key) is capped at 4096 bytes to stay within
	// the filesystem's per-inode xattr budget. Multiple files in a single
	// multipart upload receive the same metadata. If the same
	// `X-Metadata-<key>` header is sent more than once, only the first
	// value is used.
	//
	// Takes any type of body and a specified content type, and returns a wrapper object for the known response body format(s).
	//
	// Corresponds with POST /files (the `PostFiles` operationId).
	PostFilesWithBodyWithResponse(ctx context.Context, params *PostFilesParams, contentType string, body io.Reader, reqEditors ...RequestEditorFn) (*PostFilesResponse, error)

	// PostFilesComposeWithBodyWithResponse Compose multiple files into a single file using zero-copy concatenation. Source files are deleted after successful composition.
	//
	// Takes any type of body and a specified content type, and returns a wrapper object for the known response body format(s).
	//
	// Corresponds with POST /files/compose (the `PostFilesCompose` operationId).
	PostFilesComposeWithBodyWithResponse(ctx context.Context, contentType string, body io.Reader, reqEditors ...RequestEditorFn) (*PostFilesComposeResponse, error)

	// PostFilesComposeWithResponse Compose multiple files into a single file using zero-copy concatenation. Source files are deleted after successful composition.
	//
	// Takes a body of the `application/json` content type, and returns a wrapper object for the known response body format(s).
	//
	// Corresponds with POST /files/compose (the `PostFilesCompose` operationId).
	PostFilesComposeWithResponse(ctx context.Context, body PostFilesComposeJSONRequestBody, reqEditors ...RequestEditorFn) (*PostFilesComposeResponse, error)

	// PostFreezeWithResponse Freeze user/pty cgroups before pause. Written directly by envd to avoid Process.Start / shell overhead under load.
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with POST /freeze (the `PostFreeze` operationId).
	PostFreezeWithResponse(ctx context.Context, reqEditors ...RequestEditorFn) (*PostFreezeResponse, error)

	// PostFsfreezeWithResponse Freeze the guest rootfs (FIFREEZE) before a filesystem-only pause so it is flushed to a consistent on-disk state, closing the sync->pause race. Idempotent. On a successful filesystem-only pause the VM is rebooted, so no thaw is needed; the orchestrator thaws only on the pause-failure path.
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with POST /fsfreeze (the `PostFsfreeze` operationId).
	PostFsfreezeWithResponse(ctx context.Context, reqEditors ...RequestEditorFn) (*PostFsfreezeResponse, error)

	// PostFsthawWithResponse Thaw the guest rootfs (FITHAW). Intended ONLY for the orchestrator's pause-failure rollback path, so a frozen filesystem cannot leave the live VM deadlocked. Idempotent.
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with POST /fsthaw (the `PostFsthaw` operationId).
	PostFsthawWithResponse(ctx context.Context, reqEditors ...RequestEditorFn) (*PostFsthawResponse, error)

	// GetHealthWithResponse Check the health of the service
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /health (the `GetHealth` operationId).
	GetHealthWithResponse(ctx context.Context, reqEditors ...RequestEditorFn) (*GetHealthResponse, error)

	// PostInitWithBodyWithResponse Set initial vars, ensure the time and metadata is synced with the host
	//
	// Takes any type of body and a specified content type, and returns a wrapper object for the known response body format(s).
	//
	// Corresponds with POST /init (the `PostInit` operationId).
	PostInitWithBodyWithResponse(ctx context.Context, contentType string, body io.Reader, reqEditors ...RequestEditorFn) (*PostInitResponse, error)

	// PostInitWithResponse Set initial vars, ensure the time and metadata is synced with the host
	//
	// Takes a body of the `application/json` content type, and returns a wrapper object for the known response body format(s).
	//
	// Corresponds with POST /init (the `PostInit` operationId).
	PostInitWithResponse(ctx context.Context, body PostInitJSONRequestBody, reqEditors ...RequestEditorFn) (*PostInitResponse, error)

	// GetMetricsWithResponse Service stats
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /metrics (the `GetMetrics` operationId).
	GetMetricsWithResponse(ctx context.Context, reqEditors ...RequestEditorFn) (*GetMetricsResponse, error)

	// PostUnfreezeWithResponse Unfreeze user/pty cgroups. Intended ONLY for the orchestrator's pause-failure rollback path; the normal resume thaw happens via /init's deferred unfreeze, not here.
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with POST /unfreeze (the `PostUnfreeze` operationId).
	PostUnfreezeWithResponse(ctx context.Context, reqEditors ...RequestEditorFn) (*PostUnfreezeResponse, error)
}

